using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.Drawing;
using System.IO;
using System.Linq;
using System.Web.Script.Serialization;

internal static class PetsVerification {
    static void Check(bool ok,string message){if(!ok)throw new Exception(message);}
    static void Feed(PetSignal signal,byte[] b,double t,string flow="A"){signal.Consume(b,0,b.Length,t,flow);}
    static byte[] Soul(params int[] entries){var b=new List<byte>{0x0d,0x90,(byte)(entries.Length/2)};for(int i=0;i<entries.Length;i++)b.AddRange(BitConverter.GetBytes(entries[i]));return b.ToArray();}
    static byte[] Collection(int id,int level,int points){var b=new List<byte>{0,0x90,0,0,0,0,1};b.AddRange(BitConverter.GetBytes(id));b.AddRange(BitConverter.GetBytes(id));b.AddRange(BitConverter.GetBytes(level));b.Add(1);b.AddRange(BitConverter.GetBytes(id));b.AddRange(BitConverter.GetBytes(points));return b.ToArray();}
    internal static void Replay(string root,string frames){using(var assets=new PetAssets(root)){Check(assets.Ready,"Embedded assets");var signal=new PetSignal(assets,root,false);signal.Configure(true);var json=new JavaScriptSerializer{MaxJsonLength=1000000};int collections=0,gains=0,verified=0;foreach(string line in File.ReadLines(frames)){var row=json.Deserialize<Dictionary<string,object>>(line);string hex=Convert.ToString(row["hex"]);var b=new byte[hex.Length/2];for(int i=0;i<b.Length;i++)b[i]=Convert.ToByte(hex.Substring(i*2,2),16);if(b.Length<2)continue;int op=(b[0]<<8)|b[1];var before=op==0x0D90?signal.Read():null;Feed(signal,b,Convert.ToDouble(row["ts"]),Convert.ToString(row["stream"]));if(op==0x0090)collections++;if(op==0x0D90){gains++;var after=signal.Read();if(b.Length==11&&b[2]==1){int id=(int)BitConverter.ToUInt32(b,3),amount=(int)BitConverter.ToUInt32(b,7);var old=before.Progress(id);var current=after.Progress(id);if(before.Live&&old!=null&&current!=null){Check(current.Total==old.Total+amount,"Actual soul gain agrees with prior same-profile collection");verified++;if(id==1034)Check(current.Level==2&&current.Current==6&&current.Remaining==69,"Actual Giant Sparkie6/75 after+1");}}}}Check(collections>0&&signal.Read().Totals.Count>0,"Actual collections accepted with own identity");if(gains>0)Check(verified>0,"Actual gains validated");File.WriteAllText(Path.Combine(root,"pets-replay-test.txt"),"PASS: actual production-decoded collection packets="+collections+"; soul gain packets="+gains+"; gains checked against live scoped baseline="+verified+". Replay only; live game comparison pending.");}}
    internal static void Run(string root){using(var assets=new PetAssets(root)){Check(assets.Ready,"Pet assets ready: "+assets.Error);Check(assets.Pets.Count==207&&assets.Worlds.Count==6,"Complete catalogue and offline maps");Check(assets.Maps(1038).SequenceEqual(new[]{1010,1110}),"Airon has confirmed Verteron/Altgard maps");Check(assets.Locations.Values.Count(p=>p.Count>0)==160,"Exactly 160 pets have recorded coordinates");
        foreach(long n in new long[]{0,4,5,29,30,104,105}){var p=PetProgress.From(n);Check(p.Level==(n<5?0:n<30?1:n<105?2:3),"Cumulative stage boundaries");}
        var notices=new List<PetToast>();PetToast.Add(notices,1034,1,0,5);PetToast.Add(notices,1038,1,.5,5);var other=notices[0];double otherExpiry=other.Expires;PetToast.Add(notices,1034,1,1,5);Check(notices[0].Opacity(1)==1&&notices[0].Amount==2,"Repeated visible soul gain must never restart from transparent");Check(other.Expires==otherExpiry&&object.ReferenceEquals(notices[1],other),"Repeated pet gain cannot restart other cards");double beforeFade=notices[0].Opacity(5.9);PetToast.Add(notices,1034,1,5.9,5);Check(Math.Abs(notices[0].Opacity(5.9)-beforeFade)<.000001&&notices[0].Opacity(5.98)>beforeFade,"New soul during fade-out reverses smoothly without an opacity jump");PetToast.Add(notices,1034,1,11,5);Check(notices[0].Amount==1&&notices[0].Opacity(11)==0,"Expired cards start a new independent fade");PetToast.Add(notices,1034,1,11.08,5);Check(Math.Abs(notices[0].Opacity(11.08)-.5)<.000001,"Repeated gain preserves partial fade-in opacity");
        var signal=new PetSignal(assets,root,true);signal.Configure(true);byte[] own=EnemyTargetVerification.Player(123,"PetsTest",10000,12000,true);Feed(signal,own,1);Check(!signal.Read().Live&&signal.Read().Totals.Count==0,"Identity alone does not fabricate a collection");Feed(signal,Collection(1034,2,5),2);var baseline=signal.Read();Check(baseline.Live&&baseline.Exact&&baseline.Progress(1034).Current==5,"Authoritative own collection");Feed(signal,Soul(1034,1),3);Check(signal.Read().Progress(1034).Current==6&&signal.Read().Progress(1034).Remaining==69&&signal.Drain().Length==1,"Soul increment uses within-stage progress");
        Feed(signal,Soul(1034,1),3);Check(signal.Read().Progress(1034).Current==7,"Equal amount/time is not evidence of a duplicate; TCP pipeline handles retransmission");signal.Drain();var crystal=Soul(1034,5);crystal[0]=0x11;Feed(signal,crystal,4);Check(signal.Read().Progress(1034).Current==7,"Crystals cannot change pet totals");Feed(signal,Soul(1034,10),5,"other");Check(signal.Read().Progress(1034).Current==7,"Foreign flow isolation");
        var bad=Soul(1034,2,1038,1);Array.Resize(ref bad,bad.Length-1);Feed(signal,bad,6);Check(signal.Read().Progress(1034).Current==7&&!signal.Read().Exact,"Truncated batch never partially mutates counters");Feed(signal,Collection(1034,2,74),7);signal.Pin(1034,true);Feed(signal,Soul(1034,1),8);Check(signal.Read().Progress(1034).Level==3&&signal.Drain().All(e=>e.Id!=1034),"MAX stops generating soul popups");signal.Pin(1034,true);Check(signal.Read().Pins.Length==0,"Completed pets cannot be newly pinned");
        Feed(signal,Collection(1038,2,38),9);signal.Pin(1038,true);signal.Save(10,true);var restored=new PetSignal(assets,root,true);Check(restored.Read().Name=="PetsTest"&&!restored.Read().Live&&restored.Read().Pins.Contains(1038),"Saved profiles/pins are historical until fresh collection");Feed(signal,EnemyTargetVerification.Player(456,"AnotherPet",10000,12000,true),10,"B");Check(!signal.Read().Live&&signal.Read().Pins.Length==0,"Character and connection transition do not inherit live totals/pins");Feed(signal,Collection(1038,1,12),11,"B");Check(signal.Read().Progress(1038).Current==12,"New character baseline");signal.Reset();Check(!signal.Read().Live,"Reset invalidates live authority but retains historical profile");
        var ordered=new PetSignal(assets,root,false);ordered.Configure(true);Feed(ordered,Collection(1034,2,5),1);Feed(ordered,Soul(1034,1),2);Feed(ordered,own,3);Check(ordered.Read().Progress(1034).Current==6,"Collection and gain before own identity are scoped and reconciled");
        var random=new Random(8);for(int i=0;i<2000;i++){var bytes=new byte[random.Next(0,180)];random.NextBytes(bytes);if(bytes.Length>1){bytes[0]=(byte)(i%2==0?0:0x0d);bytes[1]=0x90;}Feed(ordered,bytes,10+i);}Check(ordered.Read().Totals.Count<=512,"Malformed reader remains bounded");
        using(var paint=new PetCardPainter())using(var bitmap=paint.Render(assets,new PetOptions(),"es",1038,PetProgress.From(68),false,1,true)){Check(bitmap.GetPixel(bitmap.Width/2,bitmap.Height/2).A<130,"White glass remains translucent");bitmap.Save(Path.Combine(root,"designs","pet-card-es.png"));}
        using(var owner=new EnergyOverlay(root,true)){using(var overlay=new PetsOverlay(owner,owner.Pets,true))overlay.VerifyNative(root);var c=owner.Configuration;c.Language="es";owner.ApplyConfiguration(c);var settings=new HelperSettings(owner);try{settings.VerifyPets(root);var atlas=new PetAtlasWindow(owner,owner.Pets);try{atlas.Verify(root);}finally{atlas.Close();}}finally{settings.Close();}owner.Pets.VerifyIdle();}
        File.WriteAllText(Path.Combine(root,"pets-test.txt"),"PASS: complete assets/maps, ID-selected locations, 5/25/75 and105 MAX, own collection and batch gains, no crystal/kill attribution, flow/character isolation, truncated atomicity, pending identity reconciliation, historical persistence, completed exclusion, malformed bounds, translucent rendering, preview cache and settings/registry.");
    }}
}
